CAT = "cacarpReno"; SEG = "REN"
# MWA G: renovation-specific support activities (G-21) and construction activities (G-22).
# RSOS 2022 weights 48/52.
Q = [
("Before demolishing finishes in a house built in the 1970s, what should be done first?",
 "Test for asbestos", ["Remove all the windows", "Shut off the heating", "Order the new materials"],
 "Drywall compound, plaster, vinyl tile and insulation from that era may contain asbestos. A hazardous materials survey must come before disturbing them."),
("What hazard is most likely when sanding old painted trim in a pre-1960 home?",
 "Lead dust", ["Silica dust", "Asbestos fibres", "Carbon monoxide"],
 "Paint applied before the 1960s often contains lead. Sanding or heat stripping releases toxic dust, so test first and use lead-safe work practices."),
("Loose, granular insulation that looks like grey-brown pebbles is found in an attic. What should be assumed?",
 "It may contain asbestos", ["It is safe cellulose", "It is fibreglass batts", "It is mineral wool"],
 "Vermiculite insulation may contain asbestos. Leave it undisturbed and have it tested by a qualified person."),
("Who should disconnect electrical and gas services before a renovation?",
 "Licensed trades or the utility", ["The carpenter on the job", "The homeowner alone", "The demolition labourer on site"],
 "Disconnecting and capping electrical and gas services is regulated work for licensed electricians, gas fitters or the utility. Requirements vary by province."),
("How can you tell a wall is likely load-bearing?",
 "Joists bear on its top plate", ["It has a door opening", "It is an inside partition", "It runs parallel to joists"],
 "A wall that floor or ceiling joists rest on, often near the middle of the house and perpendicular to the joists, is usually carrying load. Confirm before removing it."),
("Before removing a load-bearing wall, what must be built?",
 "Temporary shoring walls", ["The new finish ceiling", "A new floor deck", "The replacement trim"],
 "Temporary walls on one or both sides carry the joists while the wall is removed and the new beam is installed. Size them for the load they will carry."),
("How should demolition generally proceed in a room?",
 "From the top down", ["From the bottom up", "From the centre out", "Walls before the ceiling"],
 "Working top down, ceiling then walls then floor, keeps debris from falling onto finished work below and avoids leaving unsupported material overhead."),
("Why is plastic sheeting and negative air used during interior renovation?",
 "To keep dust out of lived-in rooms", ["To speed up drywall drying", "To cut the heating bill", "To protect the new flooring"],
 "Containment walls and a fan exhausting to the outside keep dust from spreading to occupied parts of the home, especially important with hazardous materials."),
("What is a permit usually needed for in a renovation?",
 "Structural changes", ["Repainting a bedroom", "Replacing a door handle", "Laying a rug"],
 "Structural work, new openings in bearing walls, and changes to plumbing, electrical or egress usually need a permit. What else needs one varies by municipality."),
("Mould covers a large area of drywall. What should be done?",
 "Remove it under containment", ["Paint over it with primer", "Wipe it with water", "Cover it with new drywall"],
 "Mouldy porous materials are removed, not cleaned, using containment and respiratory protection. The moisture source must also be fixed or the mould returns."),
("A notched floor joist has cracked. What is a common repair?",
 "Sister a new joist alongside", ["Fill the crack with glue", "Add a shim under the floor", "Screw through the crack"],
 "Sistering fastens a new full-length member beside the damaged joist, bearing on the same supports, to restore its strength. Follow an engineer's detail for major damage."),
("What does underpinning a foundation do?",
 "Extends it deeper or wider", ["Waterproofs the outside", "Insulates the basement", "Levels the basement slab"],
 "Underpinning places new footing support below or beside an existing foundation, done in short sections so the building is never left unsupported."),
("When adding a door opening to an existing bearing wall, what carries the load above?",
 "A properly sized header", ["The new door frame", "The drywall over it", "Extra cripple studs above it"],
 "A header sized for the span and load, supported on jack studs to the floor below, carries the load around the new opening."),
("New framing must line up with an old wall that is out of plumb. What is the usual approach?",
 "Shim or plane to match", ["Tear out the old wall", "Build it plumb and leave the gap", "Fill the gap with caulk"],
 "Shimming or planing the new framing lets new finishes meet the old surface cleanly, unless the existing wall is being rebuilt anyway."),
("How is an old floor levelled before laying new flooring?",
 "Use levelling compound or shims", ["Add more nails to the joists", "Lay a thicker finish floor", "Use extra flooring adhesive to fill"],
 "Self-levelling underlayment fills low spots, and shims or planing correct joists, to give a flat base. The finish floor cannot correct a wavy subfloor."),
("Why should the existing finish heights be checked before a new floor goes in?",
 "To meet doors and other floors", ["To set the paint colours", "To order the right length of trim nails", "To check the heating ducts"],
 "A thicker floor can leave doors dragging and create a trip edge at the next room. Plan transitions and door undercuts in advance."),
("What is the safest way to find hidden pipes or wires before cutting into a wall?",
 "Scan, then cut a small hole", ["Cut it with a reciprocating saw", "Hammer through to look", "Drill a row of holes"],
 "A scanner and a small exploratory opening reveal services before making the full cut. Shut off any service found nearby before going further."),
("When opening an exterior wall in an older home, what is often missing?",
 "An air and vapour barrier", ["Wall studs at regular spacing", "A doubled top plate", "Exterior board sheathing"],
 "Many older walls have no continuous air and vapour barrier. Adding insulation without one can cause condensation, so the assembly must be upgraded properly."),
("Before adding a second storey to a house, what must be confirmed?",
 "The foundation can carry it", ["The roof colour matches", "The windows can be reused", "The siding can stay on"],
 "The existing footings, foundation and framing must be checked, usually by an engineer, to confirm they can carry the extra load."),
("Why is a hazardous materials survey needed before demolishing in an older building?",
 "To protect workers and occupants", ["To set the project price", "To find materials that can be reused", "To book the waste bins"],
 "Disturbing asbestos, lead or mould without controls exposes workers and occupants to serious hazards. Provincial regulations set the rules for surveys and removal."),
]
